import{I as o,o as d,c as u,j as t,a as i,J as s,w as r,b6 as g}from"./chunks/framework.BUXTSoD9.js";const h={style:{margin:"50px 0"}},P=JSON.parse('{"title":"找到好點子 - 從使用者需求到有人買單","description":"學習如何從日常痛點中發現商業機會，掌握需求分析的系統方法論，把普通想法打磨成使用者願意付費的產品概念。","frontmatter":{"title":"找到好點子 - 從使用者需求到有人買單","description":"學習如何從日常痛點中發現商業機會，掌握需求分析的系統方法論，把普通想法打磨成使用者願意付費的產品概念。"},"headers":[],"relativePath":"zh-tw/stage-1/finding-great-idea/index.md","filePath":"zh-tw/stage-1/finding-great-idea/index.md"}'),q={name:"zh-tw/stage-1/finding-great-idea/index.md"},m=Object.assign(q,{setup(c){const a="約 <strong>3 小時</strong>";return(b,l)=>{const p=o("ChapterIntroduction"),n=o("StepBar"),e=o("ClientOnly");return d(),u("div",null,[l[1]||(l[1]=t("h1",{id:"初級二-找到好點子",tabindex:"-1"},[i("初級二：找到好點子 "),t("a",{class:"header-anchor",href:"#初級二-找到好點子","aria-label":"Permalink to “初級二：找到好點子”"},"​")],-1)),l[2]||(l[2]=t("h2",{id:"本章導讀",tabindex:"-1"},[i("本章導讀 "),t("a",{class:"header-anchor",href:"#本章導讀","aria-label":"Permalink to “本章導讀”"},"​")],-1)),s(p,{duration:a,tags:["需求挖掘","產品思維","使用者分析","商業模式"],coreOutput:"3 個經過驗證的產品概念",expectedOutput:"可落地的創業/產品方向"},{default:r(()=>[...l[0]||(l[0]=[t("p",null,[i("前面我們學會了用 AI IDE 做東西，但有一個更根本的問題："),t("strong",null,"做什麼？")],-1),t("p",null,[i('很多人一上來就想"做個 AI 工具"、"搞個社交平臺"，結果做出來的東西沒人用。問題出在哪？'),t("strong",null,"沒有找到真需求"),i("。")],-1),t("p",null,[i("更殘酷的現實是："),t("strong",null,"很多產品雖然解決了問題，但使用者就是不願意買單。")],-1),t("p",null,"這一章，我們將透過小明的故事，學習如何找到值得做的產品方向。",-1),t("p",null,[i("學完這一章，你將擁有一套"),t("strong",null,"完整的找點子方法論"),i("，以及 3 個經過驗證的產品概念。")],-1)])]),_:1}),t("div",h,[s(e,null,{default:r(()=>[s(n,{active:0,items:[{title:"Step 1",description:"建立判斷標準"},{title:"Step 2",description:"挖掘日常痛點"},{title:"Step 3",description:"橫向切分人羣"},{title:"Step 4",description:"縱向深挖場景"},{title:"Step 5",description:"驗證需求真偽"},{title:"Step 6",description:"打磨產品概念"}]})]),_:1})]),l[3]||(l[3]=g(`<h2 id="step-1-建立判斷標準-——-什麼樣的需求使用者願意買單" tabindex="-1">Step 1：建立判斷標準 —— 什麼樣的需求使用者願意買單 <a class="header-anchor" href="#step-1-建立判斷標準-——-什麼樣的需求使用者願意買單" aria-label="Permalink to “Step 1：建立判斷標準 —— 什麼樣的需求使用者願意買單”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">為什麼這一章很重要？</p><p>有人可能會覺得奇怪：&quot;這不是一門教 Vibe Coding 的課嗎？為什麼要先學&#39;找需求&#39;？直接開始寫程式碼不行嗎？&quot;</p><p>確實，市面上很多程式設計課都是直接教你做專案：做個 Todo List、做個計算器、做個個人部落格……這些專案確實能幫你熟悉語法和工具，但問題是：</p><p><strong>方向錯了，越深入錯得越多。</strong></p><p>想象一下：</p><ul><li>你花兩週時間做了一個&quot;日曆管理系統&quot;，但市面上已經有 100 個更好的</li><li>你做了一個&quot;卡路里拍照計算&quot;，但使用者用一次就解除安裝了</li><li>你做了一個&quot;個人記賬本&quot;，但連你自己都懶得用</li></ul><p>這些專案做完，你能寫在簡歷上嗎？大機率不能，因為<strong>它們沒有解決真實的問題，也沒有產生真實的價值</strong>。</p><p>更殘酷的是：既然我們要投入時間學習，為什麼不追求更好的結果？</p><p>既然 Vibe Coding 讓我們能快速把想法變成產品，那我們更應該學會<strong>找到值得做的想法</strong>。用最接近實戰的方式來訓練自己——不是做&quot;練習專案&quot;，而是做&quot;有人願意用的產品&quot;。</p><p>這就是為什麼我們要先學&quot;找到好點子&quot;。</p><hr><p><strong>筆者私以為</strong>，時間是很寶貴的，<strong>既然做，我們就做到最好</strong>，不然為什麼不去玩呢？作為責任，筆者也會竭盡全力，支援你做到最好。</p><p>就算所有人都不相信你能做好，筆者也會堅定不移盼望著你能做到最好。選擇了 vibecoding 做產品，那就試試看自己能到哪一個盡頭吧！</p></div><hr><h2 id="開篇-獨立開發程式設計師小明的故事" tabindex="-1">開篇：獨立開發程式設計師小明的故事 <a class="header-anchor" href="#開篇-獨立開發程式設計師小明的故事" aria-label="Permalink to “開篇：獨立開發程式設計師小明的故事”">​</a></h2><p>小明是一名程式設計師，工作三年了。有一天他突然想到：要不做一個健身 APP 吧，幫使用者制定健身計劃、記錄訓練資料。這個想法讓他很興奮，覺得自己終於找到了一個可以做的專案。</p><p>接下來的一年，小明幾乎把所有業餘時間都搭進去了。他做了一個功能很全的 APP——課程模組、打卡系統、社羣功能、資料分析，該有的都有。介面也做得挺好看，至少他自己覺得挺滿意的。</p><p>上線那天，小明滿懷期待。他花了不少錢做推廣，第一個月就有 5 萬人下載。看起來開局不錯，對吧？</p><p>但很快問題就來了。使用者下載之後，用一次就解除安裝了，7日留存只有 5%。他做了幾個付費功能，但幾乎沒有使用者願意掏錢。更讓他沮喪的是，Keep、薄荷健康、FitTime 這些成熟產品，功能比他全，內容比他好，使用者為什麼要換到他的 APP？</p><p>一年下來，小明虧了 20 萬。</p><p>他坐在電腦前，看著後臺慘淡的資料，心裡只有一個問題：我的 APP 做得挺好的啊，為什麼沒人用？更沒人願意買單？</p><p>小明的失敗，不是因為技術不行，也不是因為產品做得不好。說實話，他的 APP 功能挺全的，介面也挺好看的。</p><p><strong>問題出在起點。</strong></p><p>他從來沒問過一個最基本的問題：使用者真的需要嗎？</p><p>他看到健身 APP 市場很大，Keep 估值多少億，就覺得這是個好機會。但他沒搞清楚幾件事：使用者為什麼需要另一個健身 APP？和 Keep 相比，我的差異化是什麼？使用者願意為此付費嗎？</p><p><strong>方向錯了，越深入錯得越多。</strong> 他花了一年時間，把一個錯誤的方向做得越來越完善，結果只是離成功越來越遠。</p><div class="tip custom-block"><p class="custom-block-title">這一章我們做什麼</p><p>這一章，我們來幫小明覆盤一下。看看他的問題到底出在哪，然後一起找到真正有人願意買單的產品方向。</p><p>我們將分三步走：</p><p><strong>第一幕：找到真需求</strong> —— 先搞清楚什麼樣的需求使用者才願意買單</p><p><strong>第二幕：挖出好點子</strong> —— 學會從普通想法中挖掘出有價值的商業機會</p><p><strong>第三幕：AI對話打磨</strong> —— 用 AI 把想法變成可落地的產品方案</p></div><hr><h2 id="第一幕-找到真需求" tabindex="-1">第一幕：找到真需求 <a class="header-anchor" href="#第一幕-找到真需求" aria-label="Permalink to “第一幕：找到真需求”">​</a></h2><p>小明很沮喪，但沒放棄。他開始反思一個問題：到底什麼樣的需求，使用者才願意買單？</p><h3 id="小明的困惑-為什麼使用者不買單" tabindex="-1">小明的困惑：為什麼使用者不買單？ <a class="header-anchor" href="#小明的困惑-為什麼使用者不買單" aria-label="Permalink to “小明的困惑：為什麼使用者不買單？”">​</a></h3><p>他去找了幾個用過他 APP 的朋友，想聽聽他們的真實想法。</p><p>朋友 A 說：&quot;你這個 APP 做得挺好，但我已經在用 Keep 了，為什麼要切換？&quot;</p><p>朋友 B 說：&quot;你讓我記錄每次訓練，太麻煩了，我懶得記。&quot;</p><p>朋友 C 說得更直接：&quot;免費功能夠用了，我為什麼要付費？&quot;</p><p>這些回答讓小明突然明白了問題在哪。</p><p><strong>第一個問題：使用者不切換，是因為現有方案已經夠好了。</strong> Keep 等成熟產品功能已經很全，使用者習慣也養成了，遷移成本很高。你做一個差不多的產品，使用者憑什麼要換？</p><p><strong>第二個問題：使用者不願意改變習慣。</strong> 記錄訓練這件事，對使用者來說太麻煩了。如果一個產品需要使用者改變 3 個以上的習慣，大機率會失敗。</p><p><strong>第三個問題：免費替代品太多。</strong> 你的功能太通用，沒有獨特價值，使用者找不到付費的理由。</p><h3 id="什麼是真需求" tabindex="-1">什麼是真需求？ <a class="header-anchor" href="#什麼是真需求" aria-label="Permalink to “什麼是真需求？”">​</a></h3><p>小明開始研究那些讓使用者願意買單的成功產品。他發現了一個共同點：這些產品解決的都不是&quot;我覺得有用&quot;的需求，而是使用者願意為之付費、願意為之改變行為、願意為之忍受不便的那種需求。</p><p>換句話說，<strong>真需求是使用者用腳投票投出來的，不是產品經理拍腦袋想出來的。</strong></p><h3 id="案例-讓使用者買單的產品" tabindex="-1">案例：讓使用者買單的產品 <a class="header-anchor" href="#案例-讓使用者買單的產品" aria-label="Permalink to “案例：讓使用者買單的產品”">​</a></h3><p>小明研究了幾個成功案例，想搞清楚它們到底抓住了什麼痛點。</p><h4 id="美菜網-讓小餐館老闆睡個好覺" tabindex="-1">美菜網：讓小餐館老闆睡個好覺 <a class="header-anchor" href="#美菜網-讓小餐館老闆睡個好覺" aria-label="Permalink to “美菜網：讓小餐館老闆睡個好覺”">​</a></h4><p>表面上看，美菜網做的事情很簡單：幫餐館買菜。但如果你仔細想，餐館老闆為什麼要用它？</p><p>因為小餐館老闆每天凌晨 4 點就要起牀去批發市場，很辛苦，而且經常被坑。美菜網做的事情，不是簡單的&quot;電商賣菜&quot;，而是重構了整個供應鏈，讓小餐館老闆能睡個好覺。</p><p>痛點越痛，付費意願越強。省下的時間和體力，比省下的菜錢更有價值。</p><h4 id="小紅書-解決選擇困難" tabindex="-1">小紅書：解決選擇困難 <a class="header-anchor" href="#小紅書-解決選擇困難" aria-label="Permalink to “小紅書：解決選擇困難”">​</a></h4><p>表面上看，小紅書是&quot;分享海外購物心得&quot;。但使用者為什麼願意花時間在上面看筆記？</p><p>因為面對海量商品，使用者不知道什麼值得買、什麼不值得買。他們需要一個信任的人幫自己篩選，節省時間，避免踩坑。</p><p>小紅書解決的其實是兩個深層痛點：選擇困難和信任缺失。使用者願意為&quot;省時間&quot;和&quot;避坑&quot;付費，這就是為什麼小紅書能做起來。</p><hr><p>看完這些案例，小明有了一個重要發現。</p><p>使用者買單的從來不是&quot;功能&quot;，而是&quot;解決恐懼&quot;和&quot;消除焦慮&quot;。美菜網解決的是小餐館老闆對凌晨採購艱辛的恐懼，小紅書解決的是使用者對買錯東西的恐懼。</p><p><strong>恐懼驅動付費，焦慮驅動行動。</strong></p><h3 id="需求的三層-痛點、爽點、癢點" tabindex="-1">需求的三層：痛點、爽點、癢點 <a class="header-anchor" href="#需求的三層-痛點、爽點、癢點" aria-label="Permalink to “需求的三層：痛點、爽點、癢點”">​</a></h3><p>小明進一步研究，發現使用者的需求可以分為三種型別：</p><div class="tip custom-block"><p class="custom-block-title">痛點（Pain Point）—— 恐懼驅動</p><p><strong>本質：</strong> 使用者正在經歷的、讓他們感到痛苦、焦慮、不便的問題。不解決會很難受，甚至威脅到生存或安全。</p><p><strong>例子：</strong></p><ul><li>糖尿病患者不知道喫多少碳水會血糖飆升（恐懼：健康威脅）</li><li>小餐館老闆凌晨 4 點起牀去批發市場（恐懼：生存艱辛）</li></ul><p><strong>關鍵：</strong> 使用者願意為此付費，因為不解決會&quot;很痛&quot;。</p></div><div class="tip custom-block"><p class="custom-block-title">爽點（Delight Point）—— 即時滿足</p><p><strong>本質：</strong> 使用者有一個需求，能夠立即被滿足，產生即時的愉悅感。</p><p><strong>例子：</strong></p><ul><li>外賣 30 分鐘送達（即時滿足飢餓）</li><li>一鍵生成精美 PPT（省時省力的爽感）</li></ul><p><strong>關鍵：</strong> 讓使用者&quot;爽&quot;是留存的關鍵，但單獨作為付費點較弱。</p></div><div class="tip custom-block"><p class="custom-block-title">癢點（Itch Point）—— 虛擬自我</p><p><strong>本質：</strong> 使用者想要變得更好、更酷、更精緻，但不是必須的。滿足了會開心，不滿足也沒事。</p><p><strong>例子：</strong></p><ul><li>記錄每天喝了多少水（想象中的自律生活）</li><li>用 AI 給照片加藝術濾鏡（想象中的藝術品味）</li></ul><p><strong>關鍵：</strong> 使用者為&quot;癢點&quot;買單的意願較弱，因為不解決也沒事。</p></div><p>怎麼看待正確的優先順序排序？一個好的建議是：痛點 &gt; 爽點 &gt; 癢點</p><p>為什麼？</p><ol><li><strong>痛點是生存需求：</strong> 不解決會死（或很難受），使用者不得不買單。是&quot;止痛藥&quot;。</li><li><strong>爽點是即時獎賞：</strong> 讓使用者爽，使用者就會來。是&quot;海洛因&quot;（褒義的上癮機制）。</li><li><strong>癢點是慾望滿足：</strong> 可有可無，最容易被砍掉。是&quot;維生素&quot;或&quot;奢侈品&quot;。</li></ol><p><strong>關鍵洞察：</strong> 很多產品經理犯的錯誤是：用痛點的方式去推銷癢點的產品。</p><p>比如：&quot;記錄喝水能讓你更健康&quot;——喝水確實健康，但不記錄也不會不健康。這是把癢點包裝成痛點，使用者不會買賬。</p><h3 id="驗證真需求的5步法" tabindex="-1">驗證真需求的5步法 <a class="header-anchor" href="#驗證真需求的5步法" aria-label="Permalink to “驗證真需求的5步法”">​</a></h3><p>小明想：<strong>那我有一個想法時，怎麼快速判斷它是否值得投入？</strong></p><p>他學習了產品經理常用的 5 步判斷法（詳細內容見附錄A）：</p><ol><li><p><strong>第一步：直接和真實使用者聊天，瞭解他們現在的做法</strong></p><p>找到 10 個目標使用者。問他們：&quot;你現在怎麼解決這個問題？&quot; 如果使用者已經在用某種方法，說明問題確實存在。如果使用者說不需要解決，那可能不是真需求。</p></li><li><p><strong>第二步：分析使用者現有的替代方案，找出你的優勢</strong></p><p>使用者現在可能用其他產品、Excel、靠記憶，或者忍受著不解決。你需要弄清楚這些方案有什麼缺點。你的產品要比它們好很多，使用者才願意換。</p></li><li><p><strong>第三步：測試使用者是否願意為你的產品付錢</strong></p><p>做預售或收定金。統計願意付定金的使用者比例（越早賺上錢說明需求越正確）：</p><ul><li>超過 10%：需求真實，值得投入</li><li>5% 到 10%：需求存在，但需要打磨</li><li>低於 5%：需求可能不成立</li></ul></li><li><p><strong>第四步：估算這個市場有多大，能不能賺錢</strong></p><p>計算三個數字：目標使用者總數 × 付費意願 × 客單價。相乘後得到市場規模。如果市場太小，可能不值得做。</p></li><li><p><strong>第五步：思考你的產品有什麼護城河，防止別人抄襲</strong></p><p>考慮這些壁壘：技術難度、網路效應、品牌、成本優勢。這些能幫你長期保持競爭力。</p></li></ol><p><strong>本幕小結：小明的收穫</strong></p><ol><li><p><strong>真需求的標準</strong></p><ul><li>最重要的標準是使用者願意付費。</li><li>使用者願意為此改變行為。</li><li>沒有解決方案時，使用者會有很大損失。</li></ul></li><li><p><strong>避開假需求</strong></p><ul><li>癢點不是痛點，不能當成真需求。</li><li>市場太小，很難支撐商業模式。</li><li>方案比問題還複雜，使用者會放棄。</li></ul></li><li><p><strong>優先順序排序</strong></p><ul><li>真正的優先順序是：痛點 &gt; 爽點 &gt; 癢點。</li></ul></li></ol><p><strong>本幕輸出</strong></p><ul><li>我理解了什麼是真需求。</li><li>我掌握了需求的三層分類：痛點、爽點、癢點。</li><li>我學會了用 5 步判斷法驗證需求真偽。</li></ul><hr><h2 id="第二幕-挖出好點子" tabindex="-1">第二幕：挖出好點子 <a class="header-anchor" href="#第二幕-挖出好點子" aria-label="Permalink to “第二幕：挖出好點子”">​</a></h2><p>小明現在知道了什麼是真需求，但他還是不知道從哪裡開始。總不能憑空想一個需求出來吧？</p><p>他決定從自己最熟悉的事情開始——身邊的人和事。</p><h3 id="從自己出發-小明的姐姐" tabindex="-1">從自己出發：小明的姐姐 <a class="header-anchor" href="#從自己出發-小明的姐姐" aria-label="Permalink to “從自己出發：小明的姐姐”">​</a></h3><p>小明想起了他的姐姐。姐姐剛生完孩子，總是抱怨沒時間健身，肚子上的贅肉減不下去，整個人很焦慮。</p><p>有一天小明問她：&quot;你現在怎麼解決健身的問題？&quot;</p><p>姐姐嘆了口氣說：&quot;跟著 Keep 練吧，但那些動作不適合產後身體，做完腰更疼了。去健身房？沒人幫忙看孩子。請私教？一節課 300 到 500 塊，太貴了。自己瞎練吧，又怕受傷。&quot;</p><p>小明聽完，覺得這可能就是他要找的真需求。</p><p>姐姐的困擾其實很具體：時間碎片化，需要照顧寶寶，沒有整塊時間健身；身體有限制，腹直肌分離、盆底肌鬆弛，不能劇烈運動；心理很焦慮，身材走樣，擔心老公嫌棄，社交自卑；資訊太混亂，網上資訊太多，不知道什麼運動適合產後；還有孤獨感，沒人理解她們的處境，缺乏同伴支援。</p><p>這些都是真實的痛點，不是&quot;有也挺好&quot;的癢點。</p><hr><h3 id="橫向切分-不同人羣的需求" tabindex="-1">橫向切分：不同人羣的需求 <a class="header-anchor" href="#橫向切分-不同人羣的需求" aria-label="Permalink to “橫向切分：不同人羣的需求”">​</a></h3><p>小明意識到，&quot;健身 APP&quot;這個想法太泛了。他想做的是幫助所有人健身，但問題是，所有人的需求都不一樣。</p><p>他做了一個橫向切分，把&quot;想健身的人&quot;分成幾類（詳細方法見附錄B）：</p><p>健身增肌人羣需要精確計算蛋白質攝入，手動記錄太麻煩，他們的付費意願很高，追求效率。糖尿病患者必須嚴格控制碳水，但外出就餐很難估算，這是剛需，願意付費，復購率也高。產後媽媽想恢復身材但沒時間計算，需要簡單方案，時間敏感，需要一站式服務。外賣黨天天喫外賣不知道喫了多少熱量，這是高頻場景，但付費意願中等。考研學生需要高效學習工具，但不知道用什麼，這是剛需，但客單價低。</p><p>小明選擇了&quot;產後媽媽&quot;這個人羣。為什麼？</p><p>首先，他自己就是使用者——姐姐就是產後媽媽，他天然理解這個羣體的痛點。其次，痛點很痛——產後恢復的焦慮是真實的，不是&quot;有也挺好&quot;的癢點。第三，付費意願強——媽媽們為了恢復身材，願意花錢。第四，競爭相對不激烈——市面上沒有專門針對產後媽媽的產品。</p><div class="tip custom-block"><p class="custom-block-title">產品經理的切分邏輯</p><p>為什麼切分人羣這麼重要？</p><p>因為通用工具很難贏。大平臺已經佔據了&quot;通用&quot;市場，你很難在功能上超越它們。細分人羣的需求更痛——產後媽媽對健身的需求是剛需，普通健身者只是&quot;有也行&quot;。服務好一個小羣體，比討好所有人更容易建立口碑。細分人羣的痛點更具體，更願意為解決方案付費。</p></div><hr><h3 id="縱向深挖-完整的使用者場景" tabindex="-1">縱向深挖：完整的使用者場景 <a class="header-anchor" href="#縱向深挖-完整的使用者場景" aria-label="Permalink to “縱向深挖：完整的使用者場景”">​</a></h3><p>找到人羣后，小明沒有停留在&quot;產後健身&quot;這個單一功能上。他想更深入地理解使用者的完整場景（詳細方法見附錄C）。</p><p>他觀察了姐姐一天的生活。</p><p>早上 6 點，寶寶剛睡著，姐姐有 30 分鐘空閒。她想運動，但怕吵醒寶寶，也不知道做什麼動作安全。</p><p>上午 10 點，姐姐抱著寶寶哄睡，腰很酸。她想做一些修復運動，但手沒空。</p><p>下午 3 點，寶寶睡覺，姐姐想運動。但身體很累，不知道還能不能做。</p><p>晚上 8 點，姐姐終於有空了，但很焦慮。她看著鏡子裡的自己，覺得人生完蛋了，翻著以前的照片偷偷哭。</p><p>小明發現，姐姐的痛點不是&quot;沒有健身課程&quot;，而是&quot;產後恢復的恐懼和焦慮&quot;。</p><hr><div class="info custom-block"><p class="custom-block-title">產品經理的場景思維</p><p>很多人以為痛點就是功能需求，其實不是。痛點是場景中的情緒加上付費意願。</p><p>產後媽媽面對鏡子裡走樣的身材時，真正的痛點不是&quot;不知道怎麼健身&quot;，而是恐懼——擔心身體恢復不好，留下後遺症；焦慮——看著鏡子裡的自己，覺得人生完蛋了；無助——不知道從何開始，也沒人指導；孤獨——別人隨便生，我卻要恢復這麼久。</p><p>好的產品設計，要解決的是情緒，而不只是功能。情緒背後，是使用者付費的動力。</p></div><hr><h3 id="價值重構-從-健身app-到-產後媽媽恢復助手" tabindex="-1">價值重構：從&quot;健身APP&quot;到&quot;產後媽媽恢復助手&quot; <a class="header-anchor" href="#價值重構-從-健身app-到-產後媽媽恢復助手" aria-label="Permalink to “價值重構：從&quot;健身APP&quot;到&quot;產後媽媽恢復助手&quot;”">​</a></h3><p>基於以上分析，小明重新設計了這個產品。</p><div class="tip custom-block"><p class="custom-block-title">重構後的產品概念：&quot;產後媽媽恢復助手&quot;</p><p><strong>核心定位：</strong> 不只是健身工具，而是產後媽媽的&quot;專屬康復教練+心理支持者&quot;</p><p><strong>核心功能：</strong></p><ol><li><p><strong>碎片化訓練：</strong></p><ul><li>每次只需 10-15 分鐘</li><li>寶寶睡覺時也能練</li><li>提供&quot;抱著寶寶也能做&quot;的動作</li></ul></li><li><p><strong>產後專屬課程：</strong></p><ul><li>按產後階段分級（0-3個月、3-6個月、6個月以上）</li><li>針對腹直肌分離、盆底肌修復的專項訓練</li><li>每個動作都有&quot;產後注意事項&quot;提示</li></ul></li><li><p><strong>AI 動作糾正：</strong></p><ul><li>手機攝像頭識別動作</li><li>實時提示&quot;膝蓋太彎了&quot;、&quot;背部要挺直&quot;</li><li>避免錯誤動作傷害身體</li></ul></li><li><p><strong>心理支援社羣：</strong></p><ul><li>只有產後媽媽的私密社羣</li><li>分享恢復進度，互相鼓勵</li><li>專業心理諮詢師入駐</li></ul></li><li><p><strong>個性化方案：</strong></p><ul><li>根據生產方式（順產/剖腹產）、身體情況定製</li><li>考慮哺乳期的特殊需求</li></ul></li></ol><p><strong>商業模式：</strong></p><ul><li>基礎課程免費</li><li>高階課程：99元/月（含 AI 動作糾正、專屬方案）</li><li>一對一私教：299元/月（線上指導）</li><li>社羣會員：199元/年（含心理支援、專家答疑）</li></ul><p><strong>競爭壁壘：</strong></p><ul><li>專業性：與產後康復機構合作，有醫學背書</li><li>社羣粘性：產後媽媽的情感連線很強</li><li>資料積累：使用者身體資料越多，方案越精準</li></ul><p><strong>市場規模：</strong></p><ul><li>中國每年新生兒約 1000萬</li><li>產後康復市場約 500億</li><li>目標：服務 1% 的產後媽媽 = 10萬使用者</li><li>ARPU（每使用者平均收入）：500元/年</li><li>潛在收入：5000萬/年</li></ul></div><p>對比原始 idea 和重構後的概念：</p><table tabindex="0"><thead><tr><th>維度</th><th>原始想法</th><th>重構後</th></tr></thead><tbody><tr><td>目標使用者</td><td>所有健身人羣（大而泛）</td><td>產後媽媽（精準）</td></tr><tr><td>解決痛點</td><td>記錄訓練（癢點）</td><td>產後恢復焦慮（痛點）</td></tr><tr><td>競爭壁壘</td><td>技術（容易被複制）</td><td>專業性+社羣+資料</td></tr><tr><td>付費意願</td><td>低（免費替代多）</td><td>高（剛需+情緒價值）</td></tr><tr><td>擴充套件空間</td><td>有限</td><td>可擴充套件到孕期、備孕期</td></tr></tbody></table><p><strong>這就是從&quot;一個功能&quot;到&quot;有人買單的產品&quot;的進化。</strong></p><hr><h3 id="更多例子-從普通idea到好點子" tabindex="-1">更多例子：從普通idea到好點子 <a class="header-anchor" href="#更多例子-從普通idea到好點子" aria-label="Permalink to “更多例子：從普通idea到好點子”">​</a></h3><p>小明覺得這個方法很好用。他又用同樣的方法分析了幾個其他例子，想看看這個方法是不是通用的（詳細案例見附錄D）。</p><h4 id="例子一-從-卡路里測量-到-糖友安心喫" tabindex="-1">例子一：從&quot;卡路里測量&quot;到&quot;糖友安心喫&quot; <a class="header-anchor" href="#例子一-從-卡路里測量-到-糖友安心喫" aria-label="Permalink to “例子一：從&quot;卡路里測量&quot;到&quot;糖友安心喫&quot;”">​</a></h4><p>普通想法是拍照識別食物熱量，幫助減肥的人控制飲食。但問題是市面上已經有薄荷健康、MyFitnessPal 等成熟產品了。</p><p>小明橫向切分了一下，發現糖尿病患者這個人羣很有意思：他們必須嚴格控制碳水，但外出就餐很難估算。縱向深挖他們的場景：餐前不知道這個菜能不能喫，擔心血糖飆升；餐中需要實時提醒&quot;你已經喫了多少碳水&quot;；餐後需要記錄血糖變化，看和飲食的關係。</p><p>重構後的產品叫&quot;糖友安心喫&quot;，定位是糖尿病患者的&quot;飲食安全助手&quot;。</p><hr><h4 id="例子二-從-新聞助手-到-投研情報官" tabindex="-1">例子二：從&quot;新聞助手&quot;到&quot;投研情報官&quot; <a class="header-anchor" href="#例子二-從-新聞助手-到-投研情報官" aria-label="Permalink to “例子二：從&quot;新聞助手&quot;到&quot;投研情報官&quot;”">​</a></h4><p>普通想法是聚合各大平臺新聞，省得一個個開啟。但今日頭條、騰訊新聞等已經做得很好了。</p><p>小明橫向切分後發現，金融分析師這個人羣有特殊需求：他們需要追蹤特定行業動態，但資訊太分散。縱向深挖他們的場景：早上看 overnight 美股動態、匯率變化；上午追蹤持倉公司的公告、行業新聞；下午研究潛在投資標的，需要大量行業資訊。</p><p>重構後的產品叫&quot;投研情報官&quot;，定位是金融從業者的&quot;資訊雷達和決策助手&quot;。</p><hr><h4 id="例子三-從-校園二手平臺-到-畢業清倉助手" tabindex="-1">例子三：從&quot;校園二手平臺&quot;到&quot;畢業清倉助手&quot; <a class="header-anchor" href="#例子三-從-校園二手平臺-到-畢業清倉助手" aria-label="Permalink to “例子三：從&quot;校園二手平臺&quot;到&quot;畢業清倉助手&quot;”">​</a></h4><p>普通想法是校園二手交易平臺。但閒魚、轉轉已經做得很好了。</p><p>小明橫向切分後發現，畢業生這個人羣有特殊需求：東西太多，一個個賣太麻煩。縱向深挖他們的場景：畢業前一週就要離校，沒時間慢慢賣；不知道誰需要我的東西；議價、交貨、收款，太繁瑣。</p><p>重構後的產品叫&quot;畢業清倉助手&quot;，定位是畢業生的&quot;離校資產管家&quot;。</p><hr><h3 id="本幕小結-小明的收穫" tabindex="-1">本幕小結：小明的收穫 <a class="header-anchor" href="#本幕小結-小明的收穫" aria-label="Permalink to “本幕小結：小明的收穫”">​</a></h3><p>透過第二幕，小明明白了：</p><p><strong>1. 從自己出發</strong></p><ul><li>你自己就是使用者，天然理解這個羣體的痛點</li><li>愛好是最好的起點，熱情是最好的驅動力</li></ul><p><strong>2. 橫向切分人羣</strong></p><ul><li>不要服務&quot;所有人&quot;，找到&quot;最痛的那個人羣&quot;</li><li>越細分，越有機會，使用者付費意願越強</li></ul><p><strong>3. 縱向深挖場景</strong></p><ul><li>描述完整的使用者旅程：使用前、使用中、使用後</li><li>找到情緒觸點：恐懼、焦慮、無助、孤獨……</li></ul><p><strong>4. 價值重構</strong></p><ul><li>從&quot;功能&quot;升級為&quot;解決方案&quot;</li><li>從&quot;工具&quot;升級為&quot;助手/管家/夥伴&quot;</li></ul><hr><p>📦 <strong>本幕輸出：</strong></p><ul><li>找到了一個精準的目標使用者（產後媽媽）</li><li>理解了使用者的完整場景和真實情緒</li><li>重構了產品概念，有了明確的差異化定位</li></ul><hr><h2 id="第三幕-ai對話打磨" tabindex="-1">第三幕：AI對話打磨 <a class="header-anchor" href="#第三幕-ai對話打磨" aria-label="Permalink to “第三幕：AI對話打磨”">​</a></h2><p>小明現在有了一個明確的產品方向：產後媽媽恢復助手。但他還是不知道具體怎麼做，從哪裡開始，技術實現難度大不大。</p><p>他決定用 AI 來幫助自己打磨產品概念，把想法變成可執行的計劃。</p><h3 id="第一輪-丟擲原始想法" tabindex="-1">第一輪：丟擲原始想法 <a class="header-anchor" href="#第一輪-丟擲原始想法" aria-label="Permalink to “第一輪：丟擲原始想法”">​</a></h3><p>小明把他的想法告訴 AI：&quot;我想做一個產後媽媽恢復助手 APP，幫助產後媽媽恢復身材。但我擔心技術實現難度，特別是 AI 動作糾正這個功能，我一個人能做嗎？&quot;</p><hr><h3 id="第二輪-ai-幫助規劃-mvp" tabindex="-1">第二輪：AI 幫助規劃 MVP <a class="header-anchor" href="#第二輪-ai-幫助規劃-mvp" aria-label="Permalink to “第二輪：AI 幫助規劃 MVP”">​</a></h3><p>AI 回覆說：&quot;很好的問題！讓我們做一個 MVP（最小可行產品）規劃。&quot;</p><p>AI 建議分三個階段來做。第一階段是 1-2 個月，目標是驗證需求。不做 APP，先做一個微信小程式，只提供產後專屬課程（影片）和打卡社羣。用人工方式提供動作指導，使用者上傳影片，教練回覆。目標是驗證產後媽媽是否願意付費。</p><p>第二階段是 3-6 個月，如果第一階段驗證成功，就增加核心功能。開發 AI 動作糾正，可以用現成的 SDK，比如百度人體識別。增加個性化方案，最佳化社羣功能。</p><p>第三階段是 6-12 個月，規模化。開發獨立 APP，與產後康復機構合作，拓展到孕期、備孕期。</p><p>關於技術實現，AI 建議 AI 動作糾正使用現成的 AI 能力，比如百度、騰訊的 API，不需要從零開發，降低成本。前期用人工加 AI 混合模式，逐步過渡。</p><p>啟動成本方面，小程式開發 1-2 萬（外包）或自己用 AI IDE 做，內容製作找產後康復教練合作，推廣從媽媽羣、小紅書開始。</p><p>驗證指標是第一個月 100 個使用者，10% 付費轉化率。如果達到，說明需求真實，繼續投入；如果達不到，及時調整方向。</p><hr><h3 id="第三輪-小明提出擔憂" tabindex="-1">第三輪：小明提出擔憂 <a class="header-anchor" href="#第三輪-小明提出擔憂" aria-label="Permalink to “第三輪：小明提出擔憂”">​</a></h3><p>小明想了想，又問：&quot;我擔心內容製作的問題。產後康復課程需要專業指導，我沒有醫學背景，怎麼保證課程質量？&quot;</p><hr><h3 id="第四輪-ai-提供解決方案" tabindex="-1">第四輪：AI 提供解決方案 <a class="header-anchor" href="#第四輪-ai-提供解決方案" aria-label="Permalink to “第四輪：AI 提供解決方案”">​</a></h3><p>AI 回覆說：&quot;這是很多技術型創業者的擔憂，但有解決方案。&quot;</p><p>方案一是與專業人士合作。找產後康復教練、醫院營養科醫生合作，你提供技術和產品，他們提供專業內容，可以採用分成模式。</p><p>方案二是整合現有優質內容。初期可以用公開的產後康復影片，比如 YouTube、B站上的。自己做內容稽覈和整理，後期再製作原創內容。</p><p>方案三是使用者生成內容。鼓勵有經驗的媽媽分享自己的恢復方法，用社羣投票的方式篩選優質內容，逐步建立內容生態。</p><p>AI 建議先用方案一。具體操作是：找到 2-3 位產後康復教練，與他們談合作，你開發產品，他們提供課程。收入分成，你拿 70%，他們拿 30%。這樣既能保證內容質量，又能降低成本。前期課程製作 0 元，用分成模式，你只需要投入開發時間和推廣成本。</p><p><strong>我的建議：先用方案一</strong></p><p>具體操作：</p><ol><li>找到 2-3 位產後康復教練</li><li>與他們談合作：你開發產品，他們提供課程</li><li>收入分成：你拿 70%，他們拿 30%</li><li>這樣既能保證內容質量，又能降低成本</li></ol><p><strong>前期成本：</strong></p><ul><li>課程製作：0 元（用分成模式）</li><li>你只需要投入開發時間和推廣成本</li></ul><p>:::</p><hr><h3 id="第五輪-小明問推廣問題" tabindex="-1">第五輪：小明問推廣問題 <a class="header-anchor" href="#第五輪-小明問推廣問題" aria-label="Permalink to “第五輪：小明問推廣問題”">​</a></h3><p>小明還有最後一個擔憂：&quot;推廣成本會不會很高？怎麼找到產後媽媽這個羣體？&quot;</p><hr><h3 id="第六輪-ai-提供推廣策略" tabindex="-1">第六輪：AI 提供推廣策略 <a class="header-anchor" href="#第六輪-ai-提供推廣策略" aria-label="Permalink to “第六輪：AI 提供推廣策略”">​</a></h3><p>AI 回覆說：&quot;產後媽媽這個羣體其實很好找，推廣成本可以很低。&quot;</p><p>最推薦的是小紅書。搜尋&quot;產後恢復&quot;、&quot;腹直肌分離&quot;等關鍵詞，找到相關博主，私信合作。用&quot;免費體驗 1 個月&quot;的方式換取推廣，成本幾乎為 0。</p><p>其次是媽媽羣。搜尋微信羣、QQ 羣，以&quot;產後恢復經驗分享&quot;的名義進羣，分享乾貨內容，不要直接廣告，逐步建立信任。</p><p>還可以和醫院婦產科合作，提供免費的產後恢復指導，在醫院發放宣傳單，成本就是印刷費幾百元。或者和母嬰店合作，放置宣傳物料，購買母嬰產品贈送體驗卡，成本就是體驗卡製作費。</p><p>驗證指標是：第一個月 100 個使用者，10 個付費使用者（10% 轉化率），總推廣成本小於 1000 元，獲客成本小於 10 元每人。如果能達到這個指標，說明需求真實，可以繼續投入。</p><hr><h3 id="最終-小明有了清晰的計劃" tabindex="-1">最終：小明有了清晰的計劃 <a class="header-anchor" href="#最終-小明有了清晰的計劃" aria-label="Permalink to “最終：小明有了清晰的計劃”">​</a></h3><p>經過 6 輪對話，小明終於有了清晰的計劃。</p><p>第一階段是 1-2 個月：做一個微信小程式，找 2-3 位產後康復教練合作（分成模式），只提供產後專屬課程（影片）和打卡社羣，用人工方式提供動作指導。目標是 100 個使用者，10% 付費轉化率。</p><p>第二階段是 3-6 個月：如果第一階段驗證成功，繼續投入。增加 AI 動作糾正功能，增加個性化方案，最佳化社羣功能。</p><p>第三階段是 6-12 個月：開發獨立 APP，與產後康復機構合作，拓展到孕期、備孕期。</p><p>啟動成本很低：開發自己用 AI IDE 做（0 元），內容與教練分成（前期 0 元），推廣用小紅書加媽媽羣（小於 1000 元）。總成本小於 1000 元。</p><hr><h3 id="ai-對話打磨的5步法" tabindex="-1">AI 對話打磨的5步法 <a class="header-anchor" href="#ai-對話打磨的5步法" aria-label="Permalink to “AI 對話打磨的5步法”">​</a></h3><p>透過這個案例，小明總結出了一個與 AI 對話的標準流程（詳細內容見附錄E）。</p><p><strong>第一步：丟擲原始想法。</strong> 描述你的初步想法，哪怕很粗糙也沒關係。告訴 AI 你的擔憂，比如競爭激烈、不知道怎麼差異化等。</p><p><strong>第二步：讓 AI 幫你規劃 MVP。</strong> 最小可行產品應該包含什麼功能？分幾個階段？每個階段的目標是什麼？技術實現難度大嗎？</p><p><strong>第三步：提出你的擔憂。</strong> 技術實現難度？內容製作成本？推廣成本？使用者獲取難度？把你的顧慮都告訴 AI。</p><p><strong>第四步：讓 AI 提供解決方案。</strong> 針對你的擔憂，AI 會給出具體建議。多個方案對比，選擇最優。成本估算。</p><p><strong>第五步：最終確認計劃。</strong> 整理一個清晰的行動計劃，設定驗證指標。如果達不到，及時調整方向。</p><p><strong>提示詞模板：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我想做一個 [產品概念]，</span></span>
<span class="line"><span>但我擔心 [你的擔憂]。</span></span>
<span class="line"><span>請幫我：</span></span>
<span class="line"><span>1. 規劃一個 MVP</span></span>
<span class="line"><span>2. 給出具體的技術實現建議</span></span>
<span class="line"><span>3. 估算成本</span></span>
<span class="line"><span>4. 設定驗證指標</span></span></code></pre></div><hr><h3 id="本幕小結-小明的收穫-1" tabindex="-1">本幕小結：小明的收穫 <a class="header-anchor" href="#本幕小結-小明的收穫-1" aria-label="Permalink to “本幕小結：小明的收穫”">​</a></h3><p>透過第三幕，小明明白了三件事。</p><p><strong>第一，用 AI 對話打磨產品概念。</strong> 不要期待一次對話就得到完美答案，多輪迭代。告訴 AI 你的觀察、經歷、身邊人的反饋。如果 AI 的建議不合理，及時指出。最後一定要落到具體的行動計劃。</p><p><strong>第二，MVP 的核心原則。</strong> 最小化，只做最核心的功能。可驗證，能夠快速驗證需求是否真實。低成本，用最低的成本驗證。</p><p><strong>第三，驗證指標。</strong> 付費轉化率大於 10%，說明需求真實，值得投入。付費轉化率 5-10%，說明需求存在，但需要打磨。付費轉化率小於 5%，說明需求不成立，及時調整。</p><hr><p>📦 <strong>本章輸出：</strong></p><ul><li>有了清晰的 MVP 計劃</li><li>知道了技術實現路徑</li><li>設定了驗證指標</li></ul><hr><h2 id="終章-你的行動" tabindex="-1">終章：你的行動 <a class="header-anchor" href="#終章-你的行動" aria-label="Permalink to “終章：你的行動”">​</a></h2><h3 id="記憶口訣" tabindex="-1">記憶口訣 <a class="header-anchor" href="#記憶口訣" aria-label="Permalink to “記憶口訣”">​</a></h3><p><strong>一人一事一切入，橫切縱挖找痛點，AI對話磨概念，五步驗證再動手</strong></p><p><strong>解釋：</strong></p><ul><li><strong>一人：</strong> 從你自己出發，你天然理解這個羣體</li><li><strong>一事：</strong> 聚焦一件具體的事情，不要貪多</li><li><strong>一切入：</strong> 找到切入點，越細分越好</li><li><strong>橫切：</strong> 橫向切分人羣，找到最有付費意願的使用者</li><li><strong>縱挖：</strong> 縱向深挖場景，理解使用者的完整旅程</li><li><strong>AI對話：</strong> 用 AI 對話打磨產品概念</li><li><strong>五步驗證：</strong> 用 5 步判斷法驗證需求真偽</li></ul><hr><h3 id="課後練習" tabindex="-1">課後練習 <a class="header-anchor" href="#課後練習" aria-label="Permalink to “課後練習”">​</a></h3><p>選擇一個你日常生活中的小麻煩，用本章的方法進行擴充套件：</p><div class="tip custom-block"><p class="custom-block-title">練習任務</p><p><strong>1. 描述這個麻煩</strong>（1 句話）</p><ul><li>例子：&quot;我想做一個記賬 APP，幫助使用者記錄消費&quot;</li></ul><p><strong>2. 橫向切分：找出 3 個可能有不同需求的人羣</strong></p><ul><li>例子：小微企業主、留學生家長、自由職業者</li></ul><p><strong>3. 選擇一個人羣，縱向深挖：描述他們的完整場景和真實情緒</strong></p><ul><li>例子：留學生家長的場景——想知道孩子在外國花了多少錢，但孩子不說</li></ul><p><strong>4. 重構產品概念：從&quot;一個功能&quot;進化為&quot;一個解決方案&quot;</strong></p><ul><li>例子：&quot;留學資金管家&quot;——不只是記賬，而是讓家長對孩子的海外消費&quot;心中有數&quot;</li></ul><p><strong>5. 用驗證清單評估你的想法</strong>（見附錄F）</p><p><strong>把你的分析分享到社羣，和其他學員討論！</strong></p></div><hr><h2 id="附錄-sop-方法論" tabindex="-1">附錄：SOP 方法論 <a class="header-anchor" href="#附錄-sop-方法論" aria-label="Permalink to “附錄：SOP 方法論”">​</a></h2><h3 id="附錄a-需求分析的5步判斷法" tabindex="-1">附錄A：需求分析的5步判斷法 <a class="header-anchor" href="#附錄a-需求分析的5步判斷法" aria-label="Permalink to “附錄A：需求分析的5步判斷法”">​</a></h3><p>當你有一個想法時，如何快速判斷它是否值得投入？</p><p><strong>第一步：使用者驗證——找到10個目標使用者</strong></p><p><strong>不要問：</strong>&quot;你會用我的產品嗎？&quot;（假陽性率90%）</p><p><strong>要問：</strong></p><ol><li>&quot;你現在怎麼解決這個問題？&quot;（瞭解真實行為）</li><li>&quot;最近一週，這個問題讓你困擾了幾次？&quot;（瞭解頻率）</li><li>&quot;為瞭解決它，你花了多少錢/時間？&quot;（瞭解付費意願）</li><li>&quot;如果有個解決方案，但需要改變習慣，你願意嗎？&quot;（瞭解改變成本）</li></ol><p><strong>判斷標準：</strong></p><ul><li>如果有3個以上使用者說&quot;我每天都在為這事頭疼&quot;——可能是痛點</li><li>如果使用者說&quot;挺有意思，但我不著急&quot;——大機率是癢點</li><li>如果使用者說&quot;我現在用XX解決，但不太滿意&quot;——有機會</li></ul><p><strong>關鍵問題：</strong>使用者現在用什麼方法解決這個問題？</p><table tabindex="0"><thead><tr><th>替代方案型別</th><th>說明</th><th>機會判斷</th></tr></thead><tbody><tr><td><strong>沒有替代方案</strong></td><td>使用者默默忍受</td><td>大機會，但需要教育市場</td></tr><tr><td><strong>用很笨的方法</strong></td><td>Excel、手工、多人協作</td><td>好機會，使用者渴望更好的方案</td></tr><tr><td><strong>用多個工具拼湊</strong></td><td>A工具+B工具+C工具</td><td>好機會，整合有價值</td></tr><tr><td><strong>用成熟產品</strong></td><td>但使用者不滿意</td><td>有機會，但需要差異化</td></tr><tr><td><strong>用成熟產品</strong></td><td>使用者很滿意</td><td>機會很小，除非有顛覆式創新</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">什麼是&quot;顛覆式創新&quot;？</p><p><strong>簡單定義：</strong> 不是把產品做得更好，而是用更簡單/便宜的方式，服務之前被忽視的使用者羣體。</p><p><strong>例子：</strong></p><ul><li>傳統手機 → 智慧手機（不是功能更多，而是互動方式完全不同）</li><li>傳統計程車 → 滴滴（不是車更好，而是讓叫車變得隨時隨地）</li><li>傳統書店 → 電子書（不是書更多，而是讓攜帶和購買更方便）</li></ul><p><strong>關鍵：</strong> 顛覆式創新往往從&quot;低端市場&quot;或&quot;新使用者羣體&quot;開始，逐步向上侵蝕。</p></div><p><strong>案例：</strong></p><ul><li>糖尿病患者現在用&quot;經驗+猜測&quot;控制飲食（很笨的方法）——機會大</li><li>普通減肥者用薄荷健康（成熟產品，滿意度中等）——有機會做細分</li><li>學生用微信羣做二手交易（多個工具拼湊）——有機會做整合</li></ul><p><strong>最有效的方法：預售或定金</strong></p><p><strong>操作步驟：</strong></p><ol><li>做一個簡單的落地頁，描述你的產品概念</li><li>放上&quot;預售&quot;或&quot;預約&quot;按鈕</li><li>看有多少人願意付錢（哪怕只是1元）</li></ol><p><strong>判斷標準：</strong></p><ul><li>願意付定金的使用者 &gt; 10%：需求真實，值得做</li><li>願意付定金的使用者 5-10%：需求存在，但需要打磨</li><li>願意付定金的使用者 &lt; 5%：需求不成立，或產品概念有問題</li></ul><p><strong>注意：</strong>說&quot;我會買&quot;的人很多，真正掏錢的人才是你的目標使用者。</p><p><strong>簡單公式：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>潛在市場規模 = 目標使用者數量 × 付費意願 × 客單價</span></span></code></pre></div><p><strong>案例：校園二手交易平臺</strong></p><ul><li>目標使用者：全國大學生 4000萬</li><li>有二手交易需求的：50% = 2000萬</li><li>願意用平臺的：10% = 200萬</li><li>年交易頻次：2次</li><li>平臺抽成：5%</li><li>平均客單價：100元</li><li>潛在市場規模 = 200萬 × 2 × 100 × 5% = 2000萬/年</li></ul><p><strong>判斷標準：</strong></p><ul><li>市場規模 &gt; 10億：大賽道，值得做</li><li>市場規模 1-10億：中小賽道，可以做但天花板明顯</li><li>市場規模 &lt; 1億：小眾市場，適合副業或小而美</li></ul><p><strong>關鍵問題：</strong>如果產品做起來了，別人抄襲怎麼辦？</p><p><strong>常見的護城河型別：</strong></p><table tabindex="0"><thead><tr><th>護城河型別</th><th>說明</th><th>例子</th></tr></thead><tbody><tr><td><strong>網路效應</strong></td><td>使用者越多，產品價值越大</td><td>微信、滴滴</td></tr><tr><td><strong>資料積累</strong></td><td>資料越多，演算法越準</td><td>今日頭條、抖音</td></tr><tr><td><strong>品牌認知</strong></td><td>使用者心智佔領</td><td>可口可樂、耐克</td></tr><tr><td><strong>規模效應</strong></td><td>規模越大，成本越低</td><td>京東物流、亞馬遜</td></tr><tr><td><strong>技術專利</strong></td><td>核心技術壁壘</td><td>華為、大疆</td></tr><tr><td><strong>轉換成本</strong></td><td>使用者遷移成本高</td><td>企業軟體、作業系統</td></tr></tbody></table><p><strong>早期專案的現實：</strong></p><ul><li>大部分早期專案沒有明顯的護城河</li><li>但不要緊，關鍵是<strong>跑得快</strong></li><li>先佔領市場，再建立壁壘</li></ul><hr><h3 id="附錄b-橫向切分人羣方法" tabindex="-1">附錄B：橫向切分人羣方法 <a class="header-anchor" href="#附錄b-橫向切分人羣方法" aria-label="Permalink to “附錄B：橫向切分人羣方法”">​</a></h3><p>不要試圖服務&quot;所有XX使用者&quot;，而是找到<strong>一個特定的人羣</strong>，他們的需求更痛、更具體。</p><p><strong>第一步：列出所有可能的細分人羣</strong></p><p>針對你的產品概念，列出所有可能的人羣。</p><p><strong>第二步：評估每個人羣的商業價值</strong></p><table tabindex="0"><thead><tr><th>評估維度</th><th>說明</th></tr></thead><tbody><tr><td>痛點強度</td><td>這個人羣的需求是痛點還是癢點？</td></tr><tr><td>付費意願</td><td>願意為解決方案付多少錢？</td></tr><tr><td>市場規模</td><td>這個人羣有多少人？</td></tr><tr><td>競爭程度</td><td>現有解決方案是否令人滿意？</td></tr><tr><td>你對人羣的理解</td><td>你是否理解這個人羣？是否有接觸渠道？</td></tr></tbody></table><p><strong>第三步：選擇一個人羣深入分析</strong></p><p>選擇一個：</p><ul><li>痛點最痛</li><li>付費意願最強</li><li>你最理解</li><li>競爭相對不激烈</li></ul><p>的人羣。</p><div class="tip custom-block"><p class="custom-block-title">切分示例</p><p><strong>產品概念：</strong> 記賬 APP</p><table tabindex="0"><thead><tr><th>細分人羣</th><th>痛點</th><th>付費意願</th><th>市場規模</th><th>競爭程度</th></tr></thead><tbody><tr><td>普通上班族</td><td>記錄麻煩</td><td>低</td><td>大</td><td>高</td></tr><tr><td>小微企業主</td><td>個人/公司支出混淆</td><td>高</td><td>中</td><td>中</td></tr><tr><td>自由職業者</td><td>收入不穩定，需要預測現金流</td><td>高</td><td>中</td><td>中</td></tr><tr><td>留學生家長</td><td>想知道孩子花多少錢，但孩子不說</td><td>高</td><td>小</td><td>低</td></tr></tbody></table><p><strong>選擇：</strong> 留學生家長（痛點最痛，付費意願高，競爭相對不激烈）</p></div><hr><h3 id="附錄c-縱向深挖場景方法" tabindex="-1">附錄C：縱向深挖場景方法 <a class="header-anchor" href="#附錄c-縱向深挖場景方法" aria-label="Permalink to “附錄C：縱向深挖場景方法”">​</a></h3><p>找到人羣后，不要停留在單一功能，而是要理解使用者的<strong>完整場景</strong>。</p><p><strong>第一步：描述使用者的一天</strong></p><p>從早到晚，描述使用者在使用你的產品時的完整場景。</p><p><strong>第二步：分析每個場景的痛點</strong></p><p>在每個場景中，使用者遇到了什麼問題？有什麼情緒？</p><p><strong>第三步：找到情緒觸點</strong></p><p>恐懼、焦慮、無助、孤獨、憤怒、後悔……</p><p><strong>第四步：重構價值</strong></p><p>基於場景和情緒，重構產品價值。</p><div class="tip custom-block"><p class="custom-block-title">深挖示例</p><p><strong>人羣：</strong> 產後媽媽</p><table tabindex="0"><thead><tr><th>時間</th><th>場景</th><th>痛點</th><th>情緒</th></tr></thead><tbody><tr><td>早上6點</td><td>寶寶剛睡著，有30分鐘空閒</td><td>不知道做什麼動作安全</td><td>恐懼</td></tr><tr><td>上午10點</td><td>抱著寶寶哄睡，腰很酸</td><td>手沒空，想做修復運動</td><td>焦慮</td></tr><tr><td>下午3點</td><td>寶寶睡覺，想運動</td><td>身體很累，不知道還能不能做</td><td>無助</td></tr><tr><td>晚上8點</td><td>終於有空了</td><td>看著鏡子裡的自己，覺得人生完蛋了</td><td>抑鬱</td></tr><tr><td>長期</td><td>沒人理解</td><td>覺得只有自己這麼痛苦</td><td>孤獨</td></tr></tbody></table><p><strong>重構價值：</strong> 從&quot;健身工具&quot;升級為&quot;康復教練+心理支持者&quot;</p></div><hr><h3 id="附錄d-更多從普通idea到好點子的例子" tabindex="-1">附錄D：更多從普通idea到好點子的例子 <a class="header-anchor" href="#附錄d-更多從普通idea到好點子的例子" aria-label="Permalink to “附錄D：更多從普通idea到好點子的例子”">​</a></h3><h4 id="例子一-從-記賬app-到-留學資金管家" tabindex="-1">例子一：從&quot;記賬APP&quot;到&quot;留學資金管家&quot; <a class="header-anchor" href="#例子一-從-記賬app-到-留學資金管家" aria-label="Permalink to “例子一：從&quot;記賬APP&quot;到&quot;留學資金管家&quot;”">​</a></h4><p><strong>普通想法：</strong> 自動記賬 APP，連線銀行卡自動分類消費</p><p><strong>問題：</strong> 市面上已經有隨手記、挖財、支付寶賬單……</p><p><strong>橫向切分：</strong></p><ul><li>留學生家長：想知道孩子在外國花了多少錢，是否超支</li></ul><p><strong>縱向深挖：</strong></p><ul><li>痛點不是&quot;記賬&quot;，而是<strong>&quot;失控感&quot;</strong>——孩子花多少錢不知道、花在哪裡不知道</li><li>場景：每個月看到信用卡賬單，但孩子從來不主動說花了什麼</li></ul><p><strong>重構後：</strong> &quot;留學資金管家&quot;——不只是記賬，而是讓家長對孩子的海外消費&quot;心中有數&quot;</p><p><strong>核心功能：</strong></p><ul><li>子女消費實時同步</li><li>超支預警</li><li>每月消費分析報告</li><li>同類學生消費對比（&quot;你家孩子比平均水平多花 20%&quot;）</li></ul><hr><h4 id="例子二-從-番茄鍾工具-到-遠端工作證明" tabindex="-1">例子二：從&quot;番茄鍾工具&quot;到&quot;遠端工作證明&quot; <a class="header-anchor" href="#例子二-從-番茄鍾工具-到-遠端工作證明" aria-label="Permalink to “例子二：從&quot;番茄鍾工具&quot;到&quot;遠端工作證明&quot;”">​</a></h4><p><strong>普通想法：</strong> 番茄鍾 APP，幫助使用者專注工作</p><p><strong>問題：</strong> 手機自帶螢幕使用時間、Forest、番茄 ToDo……</p><p><strong>橫向切分：</strong></p><ul><li>遠端工作者：需要向老闆證明&quot;我真的在工作&quot;</li></ul><p><strong>縱向深挖：</strong></p><ul><li>痛點不是&quot;不專注&quot;，而是<strong>&quot;信任危機&quot;</strong>——老闆看不到我，怎麼證明我在工作？</li><li>場景：每天下班，老闆問&quot;今天工作怎麼樣？&quot;，沒法證明</li></ul><p><strong>重構後：</strong> &quot;遠端工作證明&quot;——幫遠端工作者建立與僱主的信任</p><p><strong>核心功能：</strong></p><ul><li>自動工作時間追蹤</li><li>生產力報告</li><li>螢幕活動摘要（隱私保護版）</li><li>每天自動生成&quot;工作報告&quot;，傳送給上級</li></ul><hr><h4 id="例子三-從-二手書交易-到-繪本圖書館" tabindex="-1">例子三：從&quot;二手書交易&quot;到&quot;繪本圖書館&quot; <a class="header-anchor" href="#例子三-從-二手書交易-到-繪本圖書館" aria-label="Permalink to “例子三：從&quot;二手書交易&quot;到&quot;繪本圖書館&quot;”">​</a></h4><p><strong>普通想法：</strong> 二手書交易平臺</p><p><strong>問題：</strong> 多抓魚、閒書、孔夫子舊書網……</p><p><strong>橫向切分：</strong></p><ul><li>寶媽羣體：孩子繪本看完就閒置，但買新的很貴</li></ul><p><strong>縱向深挖：</strong></p><ul><li>痛點不是&quot;買書貴&quot;，而是<strong>&quot;繪本生命週期短&quot;</strong>——孩子3歲看的書，4歲就不看了</li><li>場景：家裡堆滿了繪本，孩子都不看了，但扔掉可惜</li></ul><p><strong>重構後：</strong> &quot;繪本圖書館送到家&quot;——不是賣二手書，而是提供繪本的&quot;使用權租賃&quot;</p><p><strong>核心功能：</strong></p><ul><li>繪本訂閱制（每月寄5本適齡繪本，看完寄回換新的）</li><li>閱讀進度追蹤</li><li>適齡推薦</li><li>消毒保障</li></ul><hr><h3 id="附錄e-ai對話打磨產品概念的5步法" tabindex="-1">附錄E：AI對話打磨產品概念的5步法 <a class="header-anchor" href="#附錄e-ai對話打磨產品概念的5步法" aria-label="Permalink to “附錄E：AI對話打磨產品概念的5步法”">​</a></h3><p>透過多輪 AI 對話，把普通的 idea 逐步打磨成可落地的精準產品概念。</p><p><strong>操作：</strong></p><ul><li>描述你的初步想法（哪怕很粗糙）</li><li>告訴 AI 你的擔憂（競爭激烈、不知道怎麼差異化等）</li></ul><p><strong>提示詞：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我想做一個 [產品概念]，</span></span>
<span class="line"><span>但我發現 [問題/擔憂]。</span></span></code></pre></div><p><strong>操作：</strong></p><ul><li>讓 AI 幫你制定最小可行產品計劃</li><li>討論技術實現難度和成本</li><li>設定驗證指標</li></ul><p><strong>提示詞：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請幫我：</span></span>
<span class="line"><span>1. 規劃一個 MVP</span></span>
<span class="line"><span>2. 給出具體的技術實現建議</span></span>
<span class="line"><span>3. 估算成本</span></span>
<span class="line"><span>4. 設定驗證指標</span></span></code></pre></div><p><strong>操作：</strong></p><ul><li>技術實現難度？</li><li>內容製作成本？</li><li>推廣成本？</li><li>使用者獲取難度？</li></ul><p><strong>提示詞：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我擔心：</span></span>
<span class="line"><span>1. [擔憂1]</span></span>
<span class="line"><span>2. [擔憂2]</span></span>
<span class="line"><span>3. [擔憂3]</span></span></code></pre></div><p><strong>操作：</strong></p><ul><li>針對你的擔憂，給出具體建議</li><li>多個方案對比，選擇最優</li><li>成本估算</li></ul><p><strong>提示詞：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>針對我的擔憂，請給出具體的解決方案。</span></span></code></pre></div><p><strong>操作：</strong></p><ul><li>整理一個清晰的行動計劃</li><li>設定驗證指標</li><li>如果達不到，及時調整方向</li></ul><p><strong>提示詞：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請幫我整理一個清晰的行動計劃。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">關鍵技巧</p><ul><li><strong>多輪對話：</strong> 不要期待一次對話就得到完美答案，多輪迭代</li><li><strong>提供資訊：</strong> 告訴 AI 你的觀察、經歷、身邊人的反饋</li><li><strong>質疑 AI：</strong> 如果 AI 的建議不合理，及時指出</li><li><strong>聚焦執行：</strong> 最後一定要落到具體的行動計劃</li></ul></div><hr><h3 id="附錄f-需求驗證清單" tabindex="-1">附錄F：需求驗證清單 <a class="header-anchor" href="#附錄f-需求驗證清單" aria-label="Permalink to “附錄F：需求驗證清單”">​</a></h3><p>在決定投入時間開發之前，用以下清單驗證你的想法——<strong>核心問題是：使用者會為此買單嗎？</strong></p><div class="tip custom-block"><p class="custom-block-title">需求驗證清單</p><p><strong>1. 使用者畫像清晰度</strong></p><ul><li>☐ 能否用一句話描述目標使用者？</li><li>☐ 能否說出他們目前的替代方案是什麼？</li><li>☐ 能否描述他們使用場景的具體細節？</li><li>☐ 這個人羣有付費能力嗎？</li></ul><p><strong>2. 痛點強度評估</strong></p><ul><li>☐ 使用者現在解決這個問題要付出什麼代價？（時間/金錢/精力）</li><li>☐ 如果不解決這個問題，會有什麼後果？</li><li>☐ 使用者是否已經在尋找解決方案？</li><li>☐ 使用者願意為解決這個問題付多少錢？</li></ul><p><strong>3. 解決方案差異化</strong></p><ul><li>☐ 和現有方案相比，你的優勢是什麼？</li><li>☐ 這個優勢是否足夠讓使用者願意切換？</li><li>☐ 大平臺要複製你的功能，難度大嗎？</li><li>☐ 你的差異化是否足以支撐使用者付費？</li></ul><p><strong>4. 商業模式可行性</strong></p><ul><li>☐ 使用者願意為此付費嗎？付多少？（一定要實際測試）</li><li>☐ 獲客成本大概是多少？</li><li>☐ 使用者生命週期價值（LTV）能否覆蓋獲客成本（CAC）？</li><li>☐ 有沒有其他變現方式？（廣告、增值服務、B端等）</li></ul><p><strong>5. 快速驗證方案</strong></p><ul><li>☐ 能否用最小成本（1-2 周）做出可測試的原型？</li><li>☐ 能否找到 10 個目標使用者進行訪談？</li><li>☐ 能否設計一個實驗驗證核心假設？</li><li>☐ 能否讓使用者預付定金驗證付費意願？</li></ul></div><p><strong>不要問&quot;你會用這個產品嗎？&quot;</strong> 這種問題得到的都是假陽性回答。</p><p><strong>要問：</strong></p><ul><li>&quot;你現在怎麼解決這個問題？&quot;（瞭解真實行為）</li><li>&quot;最近一週，這個問題讓你困擾了幾次？&quot;（瞭解頻率）</li><li>&quot;如果有一個解決方案，但需要你改變現在的習慣，你願意嗎？&quot;（瞭解改變成本）</li><li>&quot;如果收費 XX 元，你會買嗎？&quot;（瞭解付費意願）</li></ul><p><strong>最好的驗證：</strong> 讓使用者預付定金。說願意付費的人很多，真正掏錢的人才是你的目標使用者。</p><p><strong>關鍵指標：</strong></p><ul><li>願意付定金的使用者比例 &gt; 10%：需求真實，值得投入</li><li>願意付定金的使用者比例 5-10%：需求存在，但需要打磨</li><li>願意付定金的使用者比例 &lt; 5%：需求不成立，或產品概念有問題</li></ul><hr><h2 id="本章小結" tabindex="-1">本章小結 <a class="header-anchor" href="#本章小結" aria-label="Permalink to “本章小結”">​</a></h2><p>在這一章，我們透過小明的故事，學習瞭如何用產品經理的視角審視產品想法——<strong>核心始終圍繞：使用者會為此買單嗎？</strong></p><div class="info custom-block"><p class="custom-block-title">核心要點</p><p><strong>1. 真需求的三個標準：</strong></p><ul><li>使用者願意為之付費（最重要的標準）</li><li>使用者願意為之改變行為</li><li>沒有解決方案時使用者會損失很大</li></ul><p><strong>2. 從普通 idea 到有人買單的產品的路徑：</strong></p><ul><li><strong>橫向切分：</strong>找到特定人羣，越細分付費意願越強</li><li><strong>縱向深挖：</strong>理解完整場景，解決情緒而不只是功能</li><li><strong>價值重構：</strong>從工具進化為解決方案，建立付費理由</li></ul><p><strong>3. 避開假需求的陷阱：</strong></p><ul><li>解決偽痛點（癢點而非痛點）</li><li>市場規模太小，無法支撐商業模式</li><li>解決方案比問題還複雜</li></ul><p><strong>4. 驗證付費意願的方法：</strong></p><ul><li>找到 10 個目標使用者深度訪談</li><li>讓使用者預付定金驗證真實意願</li><li>願意付定金的使用者比例 &gt; 10% 才值得投入</li></ul><p><strong>5. 用 AI 對話打磨產品概念：</strong></p><ul><li>多輪迭代，不斷最佳化</li><li>聚焦執行，落到行動計劃</li><li>設定驗證指標，及時調整</li></ul></div><p><strong>記住：</strong> 好的產品經理不是憑空創造需求，而是發現那些<strong>被忽視、被低估、被錯誤滿足</strong>的真實需求，並找到讓使用者願意為之買單的方式。</p><p>在下一章，我們將帶著經過驗證的想法，開始學習如何用 AI IDE 把它變成可互動的產品原型。</p>`,338))])}}});export{P as __pageData,m as default};
